function parseMedia(xattr: MaybeExtendedAttributes): { Width: number; Height: number } | undefined {
    const media = xattr?.Media;
    if (media == null || media.Width === undefined || media.Height === undefined) {
        return undefined;
    }
    const width = media.Width;
    if (typeof width !== 'number') {
        console.warn(`XAttr media width ${JSON.stringify(width)} is not valid`);
        return undefined;
    }
    const height = media.Height;
    if (typeof height !== 'number') {
        console.warn(`XAttr media height ${JSON.stringify(height)} is not valid`);
        return undefined;
    }
    return {
        Width: width,
        Height: height,
    };
}

function parseDigests(xattr: MaybeExtendedAttributes): { SHA1: string } | undefined {
    const digests = xattr?.Common?.Digests;
    if (digests == null || digests.SHA1 === undefined) {
        return undefined;
    }

    const sha1 = digests.SHA1;
    if (typeof sha1 !== 'string') {
        console.warn(`XAttr digest SHA1 ${JSON.stringify(sha1)} is not valid`);
        return undefined;
    }

    return {
        SHA1: sha1,
    };
}

